// Writes static redirect pages for every entry in redirects.manifest.json
// into the generated site. Nitro's own prerendering of routeRules redirect
// pages races under its parallel workers and nondeterministically drops
// some of the 100+ entries, so this post-build step writes them
// deterministically instead. Runs after both `nuxt build` (Vercel) and
// `nuxt generate` (CI/local); the manifest itself is regenerated by
// scripts/sync-generated-docs.sh from the generator output.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'

const root = resolve(import.meta.dirname, '..')
const outDir = join(root, '.output', 'public')
const manifest = JSON.parse(
  readFileSync(join(root, 'redirects.manifest.json'), 'utf8'),
)

const page = (to) =>
  `<!DOCTYPE html><html><head><meta http-equiv="refresh" content="0; url=${to}"></head></html>`

let written = 0
for (const { from, to } of manifest) {
  const file = join(outDir, from, 'index.html')
  mkdirSync(dirname(file), { recursive: true })
  writeFileSync(file, page(to))
  written++
}

console.log(`wrote ${written} redirect page(s) into .output/public`)
